package com.example.deskpet;
import android.app.*; import android.os.*; import android.content.*; import android.net.Uri; import android.provider.Settings; import android.widget.*; import android.view.*;
public class MainActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this); l.setOrientation(1); l.setGravity(Gravity.CENTER); l.setPadding(32,32,32,32); TextView t=new TextView(this); t.setText(getString(R.string.app_name)); t.setTextSize(26); l.addView(t); ImageView p=new ImageView(this); p.setImageResource(R.drawable.pet); l.addView(p,new LinearLayout.LayoutParams(240,240)); Button start=new Button(this); start.setText("시작하기"); l.addView(start); start.setOnClickListener(v->{if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))); Toast.makeText(this,"권한을 허용한 뒤 다시 시작을 눌러 주세요",Toast.LENGTH_LONG).show();}else{startForegroundService(new Intent(this,PetService.class));}}); Button stop=new Button(this); stop.setText("종료하기"); l.addView(stop); stop.setOnClickListener(v->stopService(new Intent(this,PetService.class))); setContentView(l); }
}
